SELECT u.id, o.amount FROM users u LEFT JOIN orders o ON o.user_id = u.id ORDER BY o.amount NULLS LAST, u.id, o.id;
SELECT u.id, o.amount FROM users u LEFT JOIN orders o ON o.user_id = u.id ORDER BY o.amount DESC NULLS FIRST, u.id, o.id;
SELECT u.id, o.amount FROM users u LEFT JOIN orders o ON o.user_id = u.id ORDER BY o.amount DESC NULLS LAST, u.id, o.id;
