SELECT u.id, o.id FROM users u RIGHT JOIN orders o ON o.user_id = u.id ORDER BY u.id NULLS LAST, o.id;
SELECT u.id, o.id FROM users u FULL JOIN orders o ON o.user_id = u.id ORDER BY u.id NULLS FIRST, o.id NULLS LAST;
SELECT u.id, o.id FROM users u FULL JOIN orders o ON o.user_id = u.id ORDER BY u.id NULLS LAST, o.id NULLS FIRST;
