SELECT u.id, AVG(o.amount) AS average FROM users u LEFT JOIN orders o ON o.user_id = u.id GROUP BY u.id ORDER BY average DESC NULLS LAST, u.id;
SELECT d.id, MIN(e.name) AS first_name FROM departments d LEFT JOIN employees e ON e.department_id = d.id GROUP BY d.id ORDER BY first_name NULLS FIRST, d.id;
SELECT d.id, MIN(e.name) AS first_name FROM departments d LEFT JOIN employees e ON e.department_id = d.id GROUP BY d.id ORDER BY first_name NULLS LAST, d.id;
SELECT u.id, o.amount AS total FROM users u LEFT JOIN orders o ON o.user_id = u.id ORDER BY total NULLS FIRST, u.id, o.id;
SELECT u.id, o.amount AS total FROM users u LEFT JOIN orders o ON o.user_id = u.id ORDER BY total DESC NULLS LAST, u.id, o.id;
SELECT u.id, o.amount FROM users u LEFT JOIN orders o ON o.user_id = u.id ORDER BY 2 NULLS FIRST, 1, o.id;
SELECT u.id, o.amount FROM users u LEFT JOIN orders o ON o.user_id = u.id ORDER BY 2 DESC NULLS LAST, 1, o.id;
SELECT u.id, o.amount + 1 FROM users u LEFT JOIN orders o ON o.user_id = u.id ORDER BY o.amount + 1 NULLS FIRST, u.id, o.id;
SELECT u.id, o.amount * 2 FROM users u LEFT JOIN orders o ON o.user_id = u.id ORDER BY o.amount * 2 NULLS LAST, u.id, o.id;
