SELECT u.id, o.amount FROM users u LEFT JOIN orders o ON o.user_id = u.id ORDER BY o.amount NULLS FIRST, u.id, o.id LIMIT 4;
SELECT u.id, o.amount FROM users u LEFT JOIN orders o ON o.user_id = u.id ORDER BY o.amount NULLS LAST, u.id, o.id LIMIT 4 OFFSET 2;
