SELECT id FROM users ORDER BY id NULLS LAST;
SELECT id FROM users ORDER BY id DESC NULLS FIRST;
SELECT id FROM users ORDER BY id DESC NULLS LAST;
SELECT name FROM users ORDER BY name NULLS FIRST;
