SELECT enabled FROM flags ORDER BY enabled DESC NULLS LAST, id;
SELECT 1 AS n ORDER BY n NULLS FIRST;
SELECT 1 AS n ORDER BY n DESC NULLS LAST;
SELECT SUM(amount) AS total FROM orders ORDER BY total NULLS FIRST;
SELECT SUM(amount) AS total FROM orders WHERE FALSE ORDER BY total NULLS LAST;
SELECT DISTINCT u.id, o.amount FROM users u LEFT JOIN orders o ON o.user_id = u.id ORDER BY o.amount NULLS FIRST, u.id;
SELECT DISTINCT u.id, o.amount FROM users u LEFT JOIN orders o ON o.user_id = u.id ORDER BY o.amount DESC NULLS LAST, u.id;
